INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Hardware > Auswahl und Komponenten > Drucker Funktion, Einsatz, Varianten > Multifunktionsdrucker
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können Multifunktionsdrucker unabhängig von den benötigten Funktionen ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Funktionen wie Scan oder Fax müssen Anforderungen entsprechen"}, {"text": "Ja", "correct": false, "because": "Anforderungen bestimmen Auswahl"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Auswahl eines Multifunktionsdruckers immer die Druckvolumen-Anforderungen berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Volumen beeinflusst Eignung und Kosten"}, {"text": "Nein", "correct": false, "because": "Anforderungen sind entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Scanfunktion eines Multifunktionsdruckers für alle Anwendungen irrelevant?', 2, '[{"text": "Nein", "correct": true, "because": "Wichtig für Digitalisierung"}, {"text": "Ja", "correct": false, "because": "Funktion oft essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Multifunktionsdrucker ohne Rücksicht auf die Netzwerkfähigkeit ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Netzwerk wichtig für Büroumgebungen"}, {"text": "Ja", "correct": false, "because": "Anwendung bestimmt Anforderung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Multifunktionsdrucker immer teurer als reine Drucker?', 2, '[{"text": "Ja", "correct": true, "because": "Zusätzliche Funktionen erhöhen Kosten"}, {"text": "Nein", "correct": false, "because": "Preisunterschied ist üblich"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor ist bei der Auswahl eines Multifunktionsdruckers am wichtigsten?', 3, '[{"text": "Nutzungsanforderungen", "correct": true, "because": "Bestimmen Funktionen und Kapazität"}, {"text": "Marke", "correct": false, "because": "Sekundär"}, {"text": "Farbe", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologie wird in den meisten Multifunktionsdruckern für den Druck verwendet?', 2, '[{"text": "Tintenstrahl", "correct": true, "because": "Flexibel und verbreitet"}, {"text": "Laser", "correct": false, "because": "Seltener, aber möglich"}, {"text": "Nadelmatrix", "correct": false, "because": "Nicht üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion ist neben dem Drucken typisch für Multifunktionsdrucker?', 2, '[{"text": "Scannen", "correct": true, "because": "Kernfunktion von MFDs"}, {"text": "3D-Druck", "correct": false, "because": "Andere Technologie"}, {"text": "Etikettendruck", "correct": false, "because": "Spezialisierte Drucker"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verbrauchsmaterial ist für Tintenstrahl-Multifunktionsdrucker essenziell?', 3, '[{"text": "Tintenpatronen", "correct": true, "because": "Für den Druckvorgang nötig"}, {"text": "Toner", "correct": false, "because": "Für Laserdrucker"}, {"text": "Farbbänder", "correct": false, "because": "Für Matrixdrucker"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil von Multifunktionsdruckern?', 2, '[{"text": "Platzersparnis", "correct": true, "because": "Kombiniert mehrere Geräte"}, {"text": "Geringere Kosten", "correct": false, "because": "Oft teurer"}, {"text": "Schnellere Druckzeit", "correct": false, "because": "Abhängig von Technologie"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte beeinflussen die Auswahl eines Multifunktionsdruckers?', 4, '[{"text": "Druckvolumen", "correct": true, "because": "Bestimmt Kapazität"}, {"text": "Scanqualität", "correct": true, "because": "Wichtig für Digitalisierung"}, {"text": "Netzwerkfähigkeit", "correct": true, "because": "Für Büroumgebungen"}, {"text": "Gewicht des Geräts", "correct": false, "because": "Weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen bieten Multifunktionsdrucker typischerweise?', 3, '[{"text": "Drucken", "correct": true, "because": "Grundfunktion"}, {"text": "Scannen", "correct": true, "because": "Digitalisierung"}, {"text": "Kopieren", "correct": true, "because": "Duplizierung"}, {"text": "3D-Druck", "correct": false, "because": "Andere Technologie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Multifunktionsdrucker?', 3, '[{"text": "Platzersparnis", "correct": true, "because": "Ein Gerät für alles"}, {"text": "Kosteneffizienz langfristig", "correct": true, "because": "Weniger Einzelgeräte"}, {"text": "Vielseitigkeit", "correct": true, "because": "Mehrere Aufgaben"}, {"text": "Geringere Anschaffungskosten", "correct": false, "because": "Oft teurer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Auswahl eines Multifunktionsdruckers auftreten?', 4, '[{"text": "Hohe Anschaffungskosten", "correct": true, "because": "Teurer als Einzelgeräte"}, {"text": "Unzureichende Druckgeschwindigkeit", "correct": true, "because": "Bei hohem Volumen"}, {"text": "Komplexe Wartung", "correct": true, "because": "Mehr Funktionen, mehr Aufwand"}, {"text": "Falsches Design", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schnittstellen können Multifunktionsdrucker unterstützen?', 3, '[{"text": "USB", "correct": true, "because": "Standardverbindung"}, {"text": "Wi-Fi", "correct": true, "because": "Drahtlose Nutzung"}, {"text": "Ethernet", "correct": true, "because": "Netzwerkfähigkeit"}, {"text": "HDMI", "correct": false, "because": "Für Video, nicht Drucker"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Multifunktionsdrucker kombinieren Drucken und Scannen. b) Sie sind immer langsamer als reine Drucker.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kombination ja, Geschwindigkeit variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Netzwerkfähigkeit ist bei Multifunktionsdruckern nützlich. b) Tintenstrahl-Multifunktionsdrucker verwenden Toner.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Netzwerk ja, Tinte statt Toner"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Multifunktionsdrucker sparen Platz im Büro. b) Sie sind für Fotodruck ungeeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Platz ja, Fotodruck möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Multifunktionsdrucker können Faxfunktionen haben. b) Druckvolumen ist bei allen Modellen unbegrenzt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fax ja, Volumen begrenzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Multifunktionsdrucker sind vielseitig einsetzbar. b) Sie sind immer teurer als Einzelgeräte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Vielseitig ja, Preis variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

